begin;
create function pg_temp.care_assert(ok boolean,label text) returns text language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;return label;end $$;
create function pg_temp.care_denied(stmt text,label text,expected text default '42501') returns text language plpgsql as $$begin begin execute stmt;exception when others then if sqlstate<>expected then raise exception 'Wrong error % for %',sqlstate,label;end if;return label;end;raise exception 'Unexpected success: %',label;end $$;
create function pg_temp.record_p(n integer,kind text,v integer default 0) returns jsonb language sql as $$select jsonb_build_object('id',('b4000000-0000-4000-8000-'||lpad(n::text,12,'0')),'patient_id','b2000000-0000-4000-8000-000000000001','event_id',('b3000000-0000-4000-8000-'||lpad(n::text,12,'0')),'specialty',kind,'version',v,'operation_key',gen_random_uuid(),'occurred_at',now()-interval '2 hours','payload',jsonb_build_object('objective','Objetivo neutro QA','evolution','not_evaluable','facts','Hechos neutros QA'),'reserved_note','','summary_body','','summary_visibility','none','request_intervention',false,'request_body','','request_due_at','','reason','','confirm_finalize',true,'confirm_publish',false)$$;
create temporary table records_fixture(name text primary key,p jsonb);
grant select,insert,update on records_fixture to authenticated;
insert into auth.users(id,email) select ('b1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'records-fixture-'||n||'@example.test' from generate_series(1,7)n;
insert into public.admin_users(user_id,role,is_active) select ('b1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,(case when n=7 then 'editor' else 'viewer' end)::public.admin_role,true from generate_series(3,7)n;
insert into public.patient_profiles(id,auth_user_id,email,display_name) select ('b2000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('b1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'records-fixture-'||n||'@example.test','Persona record QA '||n from generate_series(1,2)n;
insert into public.care_staff_capabilities(user_id,capabilities) select ('b1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,array['care.directory.read','care.patient.read','care.records.read','care.records.create']||case when n=5 then array['care.medical.create'] else array[]::text[] end from generate_series(3,5)n;
insert into public.care_staff_capabilities(user_id,capabilities) values('b1000000-0000-4000-8000-000000000006',array['care.directory.read','care.patient.read','care.records.read','care.assignments.manage','care.decisions.manage']);
insert into public.care_assignments(patient_id,professional_id,specialty,starts_at,created_by) select 'b2000000-0000-4000-8000-000000000001',('b1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case n when 3 then 'psychology' when 4 then 'recovery' when 5 then 'psychiatry' else 'direction' end,now()-interval '1 day','b1000000-0000-4000-8000-000000000006' from generate_series(3,6)n;
insert into public.care_assignments(patient_id,professional_id,specialty,starts_at,created_by) values('b2000000-0000-4000-8000-000000000002','b1000000-0000-4000-8000-000000000006','direction',now()-interval '1 day','b1000000-0000-4000-8000-000000000006');
insert into public.care_events(id,title,kind,starts_at,ends_at,professional_id,modality,status,closed_at,created_by) select ('b3000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'Sesión neutra QA '||n,case n when 2 then 'recovery' when 3 then 'psychiatry' else 'individual' end,now()-interval '2 hours',now()-interval '1 hour',('b1000000-0000-4000-8000-'||lpad((case n when 2 then 4 when 3 then 5 when 4 then 6 else 3 end)::text,12,'0'))::uuid,'in_person',case when n=5 then 'cancelled' else 'completed' end,now()-interval '30 minutes',('b1000000-0000-4000-8000-'||lpad((case n when 2 then 4 when 3 then 5 when 4 then 6 else 3 end)::text,12,'0'))::uuid from generate_series(1,6)n;
insert into public.care_event_participants(event_id,patient_id,attendance) select id,'b2000000-0000-4000-8000-000000000001',case when title like '%6' then 'pending' else 'present' end from public.care_events where id::text like 'b3000000-%';

insert into public.care_assignments(patient_id,professional_id,specialty,starts_at,created_by)values('b2000000-0000-4000-8000-000000000002','b1000000-0000-4000-8000-000000000004','recovery',now()-interval '2 months','b1000000-0000-4000-8000-000000000006');
insert into public.care_session_records(id,patient_id,event_id,author_id,specialty,occurred_at,status,revision,first_finalized_at)values('b4000000-0000-4000-8000-000000000002','b2000000-0000-4000-8000-000000000001','b3000000-0000-4000-8000-000000000002','b1000000-0000-4000-8000-000000000004','recovery',now()-interval '2 hours','final',1,now());
insert into public.care_commitments(id,patient_id,title,due_at,origin,created_by,source_record_id,review_at,verification_method)values('b5000000-0000-4000-8000-000000000001','b2000000-0000-4000-8000-000000000001','Tarea neutral QA',now()+interval '1 day','professional','b1000000-0000-4000-8000-000000000004','b4000000-0000-4000-8000-000000000002',now()+interval '2 days','Verificar tarea neutral QA');
insert into public.care_session_records(id,patient_id,event_id,author_id,specialty,occurred_at,status,revision,first_finalized_at)values('b4000000-0000-4000-8000-000000000009','b2000000-0000-4000-8000-000000000002','b3000000-0000-4000-8000-000000000002','b1000000-0000-4000-8000-000000000004','recovery',now()-interval '2 hours','final',1,now());
insert into public.care_commitments(id,patient_id,title,due_at,origin,created_by,source_record_id,review_at,verification_method)values('b5000000-0000-4000-8000-000000000002','b2000000-0000-4000-8000-000000000002','Tarea B neutral QA',now()+interval '1 day','professional','b1000000-0000-4000-8000-000000000004','b4000000-0000-4000-8000-000000000009',now()+interval '2 days','Verificar tarea B neutral QA');
create function pg_temp.week_p(n integer,shift_week integer default 0,cat text default 'SE',level text default null,pid uuid default 'b2000000-0000-4000-8000-000000000001',rubric uuid default 'c0000000-0000-4000-8000-000000000001')returns jsonb language sql security definer set search_path='' as $$
 select jsonb_build_object('id',('c4000000-0000-4000-8000-'||lpad(n::text,12,'0')),'patient_id',pid,'rubric_id',rubric,'week_start',date_trunc('week',now() at time zone 'America/Santiago')::date-shift_week*7,'version',0,'confirm',true,'reason','Revisión neutral QA','occurred_at',(date_trunc('week',now() at time zone 'America/Santiago')::date-shift_week*7+time '12:00')at time zone 'America/Santiago','evaluated_at',now(),'payload',jsonb_build_object('dimensions',(select jsonb_agg(jsonb_build_object('key',d->>'key','status',cat,'level',level,'evidence','Evidencia neutral por dimensión QA','support','Apoyo observado neutral QA','result','Resultado neutral por dimensión QA','difficulties','Sin dificultades observables QA','se_reason','Sin evidencia suficiente neutral QA','evidence_sufficient',cat='evaluated','record_ids','[]'::jsonb,'commitment_ids',case when cat='SE' then '[]'::jsonb else '["b5000000-0000-4000-8000-000000000001"]'::jsonb end,'next_commitment_id',case when cat='SE' then null else 'b5000000-0000-4000-8000-000000000001' end))from public.care_recovery_rubrics r cross join lateral jsonb_array_elements(r.dimensions)d where r.id=rubric)))$$;
create temporary table weekly_fixture(name text primary key,p jsonb);grant select,insert,update on weekly_fixture to authenticated;
select pg_temp.care_assert((select governance_state='proposal' and not criteria_enabled and created_by is null and approved_by is null and approved_at is null and effective_from is null from public.care_recovery_rubrics where document_code='ICC-REC-AUT-001'),'Exact proposal imported without fictitious approver or activation');
select pg_temp.care_assert((select jsonb_array_length(dimensions)=8 and dimensions->0->>'label'='Planificación personal' and dimensions->7->>'description'='Existe correspondencia verificable entre lo acordado y lo realizado.' and dimensions->0->'levels'->0->>'label'='Dependencia alta' and dimensions->0->'levels'->4->>'key'='SE' from public.care_recovery_rubrics where document_code='ICC-REC-AUT-001'),'Eight exact dimensions and levels including SE, not zero');
set local role anon;
select pg_temp.care_denied($$select public.care_rc_catalog()$$,'Anonymous no rubric RPC');
select pg_temp.care_denied($$select * from public.care_recovery_weeks$$,'Anonymous no weekly data');
reset role;set local role authenticated;select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000004',true);
select pg_temp.care_assert(public.care_rc_catalog()->0->>'governance_state'='proposal','Recovery reads proposal label');
select pg_temp.care_assert(jsonb_array_length(public.care_recovery_rubrics())=0,'Original record dimensions do not silently receive new proposal');
select pg_temp.care_denied($$select private.care_recovery_legacy_write('rubric_approve','{}')$$,'Legacy renamed function has no client grant');
select pg_temp.care_denied($$select public.care_recovery_write('rubric_approve',jsonb_build_object('id','c0000000-0000-4000-8000-000000000001','version',1,'confirm_approval',true,'approval_reference','Forjada QA'))$$,'Legacy generic approval cannot bypass governance','P0001');
select pg_temp.care_denied($$select public.care_rc_govern('approve',jsonb_build_object('id','c0000000-0000-4000-8000-000000000001','version',1,'confirm',true,'reference','Forjada QA'))$$,'Recovery cannot approve');
select pg_temp.care_denied($$select public.care_rc_week_write('finalize',pg_temp.week_p(1,0,'evaluated','3'))$$,'Proposal forbids levels before pilot authorization','P0001');
insert into weekly_fixture values('blank',pg_temp.week_p(1)||jsonb_build_object('confirm',false,'payload',jsonb_build_object('dimensions',(select jsonb_agg(d||jsonb_build_object('status','','se_reason','')) from jsonb_array_elements(pg_temp.week_p(1)->'payload'->'dimensions')d))));
select public.care_rc_week_write('draft',(select p from weekly_fixture where name='blank'));
select pg_temp.care_assert(public.care_rc_week_read('c4000000-0000-4000-8000-000000000001')->'draft'->'payload'->'dimensions'->0->>'status'='','Draft keeps unselected categories, no finalization');
select pg_temp.care_denied($$select public.care_rc_week_write('finalize',(select p||jsonb_build_object('version',1,'confirm',true)from weekly_fixture where name='blank'))$$,'Finalization does not guess eight categories','P0001');
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000006',true);
select pg_temp.care_denied($$select public.care_rc_week_read('c4000000-0000-4000-8000-000000000001')$$,'Direction cannot read working draft');
select pg_temp.care_denied($$select public.care_rc_govern('criteria',jsonb_build_object('id','c0000000-0000-4000-8000-000000000001','version',1,'confirm',true,'confirm_window',true,'enabled',true,'reference','Regla fixture QA'))$$,'Criteria cannot activate before approval','P0001');
select public.care_rc_govern('pilot',jsonb_build_object('id','c0000000-0000-4000-8000-000000000001','version',1,'confirm',true,'pilot_start',date_trunc('week',now() at time zone 'America/Santiago')::date-21,'pilot_end',date_trunc('week',now() at time zone 'America/Santiago')::date+6,'participants',jsonb_build_array('b2000000-0000-4000-8000-000000000002'),'reference','Autorización fixture QA, rollback'));
select pg_temp.care_denied($$select public.care_rc_govern('pilot',jsonb_build_object('id','c0000000-0000-4000-8000-000000000001','version',1,'confirm',true,'reference','Obsoleta QA'))$$,'Governance rejects stale version','40001');
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000004',true);
select pg_temp.care_denied($$select public.care_rc_week_write('finalize',pg_temp.week_p(2,1,'evaluated','3'))$$,'Pilot excludes patient outside configured participants','P0001');
-- The participant can record SE and a manual level only with their own sources.
select public.care_rc_week_write('finalize',replace(pg_temp.week_p(2,1,'evaluated','3','b2000000-0000-4000-8000-000000000002')::text,'b5000000-0000-4000-8000-000000000001','b5000000-0000-4000-8000-000000000002')::jsonb);
select pg_temp.care_assert(public.care_rc_week_read('c4000000-0000-4000-8000-000000000002')->'week'->>'mode'='pilot','Authorized participant stores experimental mode, no approval');
select public.care_rc_week_write('finalize',pg_temp.week_p(1)||jsonb_build_object('version',1));
select pg_temp.care_assert(public.care_rc_week_read('c4000000-0000-4000-8000-000000000001')->'versions'->0->'payload'->'dimensions'->0->>'level' is null,'SE is nullable, never zero');
select pg_temp.care_denied($$select public.care_rc_week_write('finalize',pg_temp.week_p(3))$$,'Unique patient week version avoids contradictory reviews','40001');
select public.care_rc_week_write('amend',pg_temp.week_p(1,0,'qualitative')||jsonb_build_object('version',2));
select pg_temp.care_assert(jsonb_array_length(public.care_rc_week_read('c4000000-0000-4000-8000-000000000001')->'versions')=2,'Qualitative amendment retains SE original and source snapshots');
select pg_temp.care_denied($$select public.care_rc_week_write('amend',pg_temp.week_p(1)||jsonb_build_object('version',2))$$,'Amendment optimistic concurrency','40001');
select pg_temp.care_denied($$select * from private.care_recovery_week_versions$$,'No direct private weekly evidence grant');
reset role;update public.care_recovery_rubrics set pilot_end=date_trunc('week',now() at time zone 'America/Santiago')::date-1 where id='c0000000-0000-4000-8000-000000000001';
set local role authenticated;select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000006',true);
select pg_temp.care_assert(public.care_rc_catalog()->0->>'governance_state'='pilot','Expired pilot does not autoapprove');
select pg_temp.care_assert(not(public.care_rc_candidate_read('b2000000-0000-4000-8000-000000000001','c0000000-0000-4000-8000-000000000001',date_trunc('week',now() at time zone 'America/Santiago')::date-7)->>'eligible')::boolean,'Pilot and disabled criteria do not create candidate');
select public.care_rc_govern('approve',jsonb_build_object('id','c0000000-0000-4000-8000-000000000001','version',2,'confirm',true,'effective_from',date_trunc('week',now() at time zone 'America/Santiago')::date-28,'reference','Aprobación fixture QA, rollback'));
select pg_temp.care_assert(not(public.care_rc_catalog()->0->>'criteria_enabled')::boolean,'Instrument approval does not enable criterion or approve patient');
select public.care_rc_govern('criteria',jsonb_build_object('id','c0000000-0000-4000-8000-000000000001','version',3,'confirm',true,'confirm_window',true,'enabled',true,'reference','Cuatro semanas comunes cerradas fixture QA, rollback'));
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000004',true);
select public.care_rc_week_write('finalize',pg_temp.week_p(10,1,'evaluated','3'));
select public.care_rc_week_write('finalize',pg_temp.week_p(11,2,'evaluated','3'));
select public.care_rc_week_write('finalize',pg_temp.week_p(12,3,'evaluated','4'));
select pg_temp.care_assert(not(public.care_rc_candidate_read('b2000000-0000-4000-8000-000000000001','c0000000-0000-4000-8000-000000000001',date_trunc('week',now() at time zone 'America/Santiago')::date-7)->>'eligible')::boolean,'Missing fourth week prevents candidate');
select public.care_rc_week_write('finalize',pg_temp.week_p(13,4,'evaluated','3'));
insert into weekly_fixture values('candidate',public.care_rc_candidate_read('b2000000-0000-4000-8000-000000000001','c0000000-0000-4000-8000-000000000001',date_trunc('week',now() at time zone 'America/Santiago')::date-7));
select pg_temp.care_assert((select(p->>'eligible')::boolean and jsonb_array_length(p->'weeks')=4 from weekly_fixture where name='candidate'),'Four closed common weeks eight dimensions yield candidate only');
select pg_temp.care_assert(jsonb_array_length(public.care_rc_weeks('b2000000-0000-4000-8000-000000000001',(now() at time zone 'America/Santiago')::date-40,(now() at time zone 'America/Santiago')::date)->'validations')=0,'Candidate never automatically creates a human validation');
select pg_temp.care_assert(not(public.care_rc_candidate_read('b2000000-0000-4000-8000-000000000001','c0000000-0000-4000-8000-000000000001',date_trunc('week',now() at time zone 'America/Santiago')::date)->>'eligible')::boolean,'Open week is excluded');
select pg_temp.care_denied($$select public.care_rc_validation_write((select p||jsonb_build_object('id',gen_random_uuid(),'patient_id','b2000000-0000-4000-8000-000000000001','decision','validated','reason','Forjada QA','confirm',true)from weekly_fixture where name='candidate'))$$,'Recovery cannot validate global goal');
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000006',true);
select public.care_rc_validation_write((select p||jsonb_build_object('id','c5000000-0000-4000-8000-000000000001','patient_id','b2000000-0000-4000-8000-000000000001','decision','validated','reason','Validación humana fixture QA, rollback','confirm',true)from weekly_fixture where name='candidate'));
select pg_temp.care_assert(public.care_rc_weeks('b2000000-0000-4000-8000-000000000001',(now() at time zone 'America/Santiago')::date-40,(now() at time zone 'America/Santiago')::date)->'validations'->0->>'decision'='validated','Direction explicit decision records author reason and immutable snapshot');
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000004',true);
select public.care_rc_week_write('amend',jsonb_set(pg_temp.week_p(11,2,'evaluated','3'),'{payload,dimensions,0,level}','"2"')||jsonb_build_object('version',1));
select pg_temp.care_assert(not(public.care_rc_candidate_read('b2000000-0000-4000-8000-000000000001','c0000000-0000-4000-8000-000000000001',date_trunc('week',now() at time zone 'America/Santiago')::date-7)->>'eligible')::boolean,'One level 2 prevents compensation with level 4');
select pg_temp.care_assert((public.care_rc_weeks('b2000000-0000-4000-8000-000000000001',(now() at time zone 'America/Santiago')::date-40,(now() at time zone 'America/Santiago')::date)->'validations'->0->>'requires_review')::boolean,'Amendment flags prior validation for review, preserves original');
select public.care_rc_week_write('amend',jsonb_set(pg_temp.week_p(11,2,'evaluated','3'),'{payload,dimensions,0}',pg_temp.week_p(11,2,'SE')->'payload'->'dimensions'->0)||jsonb_build_object('version',2));
select pg_temp.care_assert(not(public.care_rc_candidate_read('b2000000-0000-4000-8000-000000000001','c0000000-0000-4000-8000-000000000001',date_trunc('week',now() at time zone 'America/Santiago')::date-7)->>'eligible')::boolean,'SE creates a gap instead of zero or level');
select pg_temp.care_denied($$select public.care_rc_week_write('finalize',pg_temp.week_p(30)||jsonb_build_object('week_start',date_trunc('week',now() at time zone 'America/Santiago')::date+1))$$,'Weekly period starts Monday in Chile','P0001');
select pg_temp.care_denied($$select public.care_rc_week_write('finalize',pg_temp.week_p(30)||jsonb_build_object('evaluated_at',now()+interval '1 hour'))$$,'Future evaluation cannot be finalized','P0001');
select pg_temp.care_denied($$select public.care_rc_week_write('finalize',replace(pg_temp.week_p(30,5,'qualitative')::text,'b5000000-0000-4000-8000-000000000001','b5000000-0000-4000-8000-000000000002')::jsonb)$$,'References cannot cross patients even with other assignment','42501');
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000006',true);
select public.care_rc_govern('new_version',jsonb_build_object('id','c0000000-0000-4000-8000-000000000001','version',4,'confirm',true,'reference','Cambio explícito fixture QA, rollback','new_id','c0000000-0000-4000-8000-000000000002','document_version','2.0','effective_from',date_trunc('week',now() at time zone 'America/Santiago')::date-28,'dimensions',jsonb_set((select dimensions from public.care_recovery_rubrics where id='c0000000-0000-4000-8000-000000000001'),'{0,description}','"Conducta modificada en versión explícita fixture QA"')));
select pg_temp.care_assert(public.care_rc_catalog()->0->>'governance_state'='proposal' and not(public.care_rc_catalog()->0->>'criteria_enabled')::boolean,'New version returns to proposal with criteria disabled');
select pg_temp.care_assert((select dimensions->0->>'description'='Organiza y ejecuta una planificación semanal realista.' from public.care_recovery_rubrics where id='c0000000-0000-4000-8000-000000000001'),'Used v1 content and old evaluations remain immutable');
select public.care_rc_govern('approve',jsonb_build_object('id','c0000000-0000-4000-8000-000000000002','version',1,'confirm',true,'effective_from',date_trunc('week',now() at time zone 'America/Santiago')::date-28,'reference','Nueva aprobación fixture QA, rollback'));
select public.care_rc_govern('criteria',jsonb_build_object('id','c0000000-0000-4000-8000-000000000002','version',2,'confirm',true,'confirm_window',true,'enabled',true,'reference','Nueva regla fixture QA, rollback'));
select pg_temp.care_assert(not(public.care_rc_candidate_read('b2000000-0000-4000-8000-000000000001','c0000000-0000-4000-8000-000000000002',date_trunc('week',now() at time zone 'America/Santiago')::date-7)->>'eligible')::boolean,'Versions never mix to fill missing weeks');
select pg_temp.care_assert(not(public.care_rc_week_context('b2000000-0000-4000-8000-000000000001','c0000000-0000-4000-8000-000000000001',date_trunc('week',now() at time zone 'America/Santiago')::date)->>'levels_allowed')::boolean,'New approved effective version prevents new levels on old version');
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000001',true);
select pg_temp.care_denied($$select public.care_rc_catalog()$$,'Patient no rubric governance');
select pg_temp.care_denied($$select public.care_rc_week_read('c4000000-0000-4000-8000-000000000010')$$,'Patient no weekly professional evidence');
select pg_temp.care_assert((select count(*)=0 from public.care_recovery_weeks),'Patient RLS hides weekly metadata');
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000007',true);
select pg_temp.care_denied($$select public.care_rc_catalog()$$,'CMS editor without clinical capability no rubric');
select pg_temp.care_denied($$select public.care_rc_govern('approve','{}')$$,'CMS editor cannot govern instrument');
reset role;update public.care_assignments set ends_at=now() where professional_id='b1000000-0000-4000-8000-000000000004';
set local role authenticated;select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000004',true);
select pg_temp.care_denied($$select public.care_rc_week_read('c4000000-0000-4000-8000-000000000010')$$,'Revocation denies prior history');
select pg_temp.care_denied($$select public.care_rc_week_write('amend',pg_temp.week_p(11)||jsonb_build_object('version',3))$$,'Revocation denies new write');
reset role;rollback;
